-- R-058/R-093/R-094/R-095/R-097/R-098. Fresh private validation schemas only.
ALTER TABLE live_outputs ADD COLUMN invalidated_at text;
ALTER TABLE live_outputs ADD COLUMN invalidation_reason text;
ALTER TABLE live_outputs ADD CONSTRAINT native_output_shape CHECK(environment='mock' AND app_env IN('development','sandbox') AND snapshot::jsonb->>'pipeline'='native-live-output-v1' AND snapshot_hash=encode(sha256(convert_to(snapshot,'UTF8')),'hex') AND presentation_hash=encode(sha256(convert_to(presentation,'UTF8')),'hex') AND version>0 AND presentation_version BETWEEN 1 AND 200 AND attempts BETWEEN 0 AND 3 AND generation BETWEEN 0 AND 3 AND accepted_frames BETWEEN 0 AND 43224 AND encoded_frames BETWEEN 0 AND accepted_frames AND published_frames BETWEEN 0 AND 43224 AND published_duration_ms BETWEEN 0 AND 1803000 AND interruptions BETWEEN 0 AND 3 AND status IN('armed','queued','preparing','running','recovering','stopping','completed','failed','cancelled','withdrawn') AND((lease_token IS NULL)=(lease_until IS NULL)));
ALTER TABLE live_output_generations ADD CONSTRAINT native_output_generation_shape CHECK(number BETWEEN 1 AND 3 AND start_frame>=0 AND accepted_frames BETWEEN 0 AND 43224 AND encoded_frames BETWEEN 0 AND accepted_frames AND published_frames BETWEEN 0 AND 43224 AND duration_ms BETWEEN 0 AND 1803000 AND status IN('preparing','running','completed','interrupted'));
ALTER TABLE live_output_parts ADD CONSTRAINT native_output_part_shape CHECK(sequence BETWEEN 0 AND 1803 AND size BETWEEN 1 AND 33554432 AND sha256 ~ '^[a-f0-9]{64}$' AND storage_key ~ '^[a-f0-9-]{36}\.bin$' AND((kind='init' AND sequence=0 AND duration_ms=0 AND media_start_ms=0) OR(kind='segment' AND duration_ms BETWEEN 1 AND 2000 AND media_start_ms>=0)));
ALTER TABLE live_output_presentations ADD CONSTRAINT native_output_presentation_shape CHECK(version BETWEEN 1 AND 200 AND presentation_hash=encode(sha256(convert_to(presentation,'UTF8')),'hex') AND status IN('pending','applied','superseded') AND(status<>'applied' OR(generation_id IS NOT NULL AND media_frame>=0 AND applied_at IS NOT NULL)));
ALTER TABLE live_output_spans ADD CONSTRAINT native_output_span_shape CHECK(first_frame>=0 AND last_frame>=first_frame AND last_frame<43224 AND session_version>0 AND epoch>0 AND presentation_version>0 AND frame_hash=encode(sha256(convert_to(frame,'UTF8')),'hex'));
CREATE TRIGGER native_output_part_immutable BEFORE UPDATE OR DELETE ON live_output_parts FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_output_recording_link_immutable BEFORE UPDATE OR DELETE ON live_output_recordings FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_output_recording_origin_immutable BEFORE UPDATE OR DELETE ON live_recording_origins FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_output_clip_immutable BEFORE UPDATE OR DELETE ON live_recording_clips FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE FUNCTION dg_native_output_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Continuous output history cannot be deleted';END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'armed' OR NEW.version<>1 OR NEW.attempts<>0 OR NEW.generation<>0 OR NEW.accepted_frames<>0 OR NEW.encoded_frames<>0 OR NEW.published_frames<>0 OR NEW.lease_token IS NOT NULL OR NEW.invalidated_at IS NOT NULL OR NEW.withdrawn_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Output must start armed without fabricated receipts';END IF;
 ELSE
  IF to_jsonb(NEW)-ARRAY['presentation','presentation_hash','presentation_version','status','version','attempts','lease_token','lease_until','generation_id','generation','accepted_frames','encoded_frames','published_frames','published_duration_ms','interruptions','error_message','withdrawn_at','invalidated_at','invalidation_reason','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['presentation','presentation_hash','presentation_version','status','version','attempts','lease_token','lease_until','generation_id','generation','accepted_frames','encoded_frames','published_frames','published_duration_ms','interruptions','error_message','withdrawn_at','invalidated_at','invalidation_reason','updated_at'] OR NEW.version<OLD.version OR NEW.version>OLD.version+1 OR NEW.attempts<OLD.attempts OR NEW.attempts>OLD.attempts+1 OR NEW.generation<OLD.generation OR NEW.generation>OLD.generation+1 OR NEW.presentation_version<OLD.presentation_version OR NEW.presentation_version>OLD.presentation_version+1 OR NEW.accepted_frames<OLD.accepted_frames OR NEW.encoded_frames<OLD.encoded_frames OR NEW.published_frames<OLD.published_frames OR NEW.published_duration_ms<OLD.published_duration_ms OR(OLD.invalidated_at IS NOT NULL AND(NEW.invalidated_at,NEW.invalidation_reason) IS DISTINCT FROM(OLD.invalidated_at,OLD.invalidation_reason)) OR(OLD.withdrawn_at IS NOT NULL AND NEW.withdrawn_at IS DISTINCT FROM OLD.withdrawn_at) OR(OLD.status='withdrawn' AND NEW.status<>'withdrawn') OR(OLD.status='cancelled' AND NEW.status NOT IN('cancelled','withdrawn')) OR(OLD.status='completed' AND NEW.status NOT IN('completed','withdrawn')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Output identity, fixed sources, receipts and terminal states are protected';END IF;
 END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_output_guard BEFORE INSERT OR UPDATE OR DELETE ON live_outputs FOR EACH ROW EXECUTE FUNCTION dg_native_output_guard();
CREATE FUNCTION dg_native_output_span_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_OP='DELETE' OR to_jsonb(NEW)-'last_frame' IS DISTINCT FROM to_jsonb(OLD)-'last_frame' OR NEW.last_frame<>OLD.last_frame+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accepted frame spans are immutable except a sequential extension';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_output_span_guard BEFORE UPDATE OR DELETE ON live_output_spans FOR EACH ROW EXECUTE FUNCTION dg_native_output_span_guard();
CREATE FUNCTION dg_native_output_generation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_OP='DELETE' OR to_jsonb(NEW)-ARRAY['accepted_frames','encoded_frames','published_frames','duration_ms','status','helper_pid','helper_entry','ended_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['accepted_frames','encoded_frames','published_frames','duration_ms','status','helper_pid','helper_entry','ended_at'] OR NEW.accepted_frames<OLD.accepted_frames OR NEW.encoded_frames<OLD.encoded_frames OR NEW.published_frames<OLD.published_frames OR NEW.duration_ms<OLD.duration_ms OR(OLD.ended_at IS NOT NULL AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD)) OR(OLD.helper_pid IS NOT NULL AND(NEW.helper_pid,NEW.helper_entry) IS DISTINCT FROM(OLD.helper_pid,OLD.helper_entry)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Encoder generation and final counters are protected';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_output_generation_guard BEFORE UPDATE OR DELETE ON live_output_generations FOR EACH ROW EXECUTE FUNCTION dg_native_output_generation_guard();
CREATE FUNCTION dg_native_output_presentation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_OP='DELETE' OR to_jsonb(NEW)-ARRAY['status','generation_id','media_frame','applied_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','generation_id','media_frame','applied_at'] OR OLD.status<>'pending' OR NEW.status NOT IN('applied','superseded') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Presentation history requires a separate encoder receipt';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_output_presentation_guard BEFORE UPDATE OR DELETE ON live_output_presentations FOR EACH ROW EXECUTE FUNCTION dg_native_output_presentation_guard();
CREATE FUNCTION dg_native_output_member_invalidate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_OP='DELETE' OR(NEW.tenant_id,NEW.role,NEW.workspace_ids) IS DISTINCT FROM(OLD.tenant_id,OLD.role,OLD.workspace_ids) THEN UPDATE live_outputs SET invalidated_at=dg_utc_now(),invalidation_reason='原连续媒体创建人的组织、角色或空间权限已变化；重新授权不恢复旧输出。',version=version+1,updated_at=dg_utc_now() WHERE actor_id=OLD.user_id AND invalidated_at IS NULL;END IF;RETURN NULL;
END $dg$;
CREATE TRIGGER native_output_member_invalidate AFTER UPDATE OR DELETE ON memberships FOR EACH ROW EXECUTE FUNCTION dg_native_output_member_invalidate();

ALTER TABLE _dg_native_asset_origins DROP CONSTRAINT native_asset_source_kind;
ALTER TABLE _dg_native_asset_origins ADD CONSTRAINT native_asset_source_kind CHECK(source_kind IN('private_upload','package_import','video_upload','system_speech','media_processing','recording','ae_media','live_recording'));
CREATE TABLE _dg_native_live_captures(recording_id text PRIMARY KEY REFERENCES live_recordings(id),output_id text NOT NULL UNIQUE REFERENCES live_outputs(id),receipt text NOT NULL,receipt_hash text NOT NULL CHECK(receipt_hash=encode(sha256(convert_to(receipt,'UTF8')),'hex')),created_at text NOT NULL);
CREATE TRIGGER native_live_capture_immutable BEFORE UPDATE OR DELETE ON _dg_native_live_captures FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
ALTER TABLE live_recordings ADD CONSTRAINT native_live_capture_shape CHECK(capture_kind='local_continuous_output' AND status IN('ready','withdrawn') AND attempts=1 AND version>0 AND asset_id IS NOT NULL AND size BETWEEN 1 AND 134217728 AND sha256 ~ '^[a-f0-9]{64}$' AND snapshot::jsonb->>'pipeline'='native-live-output-capture-v1' AND snapshot_hash=encode(sha256(convert_to(snapshot,'UTF8')),'hex') AND source_guard_hash=encode(sha256(convert_to(source_guard,'UTF8')),'hex'));
CREATE FUNCTION dg_native_live_capture_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_OP='DELETE' OR to_jsonb(NEW)-ARRAY['status','version','withdrawn_at','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','version','withdrawn_at','updated_at'] OR NEW.version<>OLD.version+1 OR NEW.status<>'withdrawn' OR NEW.withdrawn_at IS NULL OR OLD.status='withdrawn' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Actual recording receipt and capture cannot be rewritten';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_live_capture_guard BEFORE UPDATE OR DELETE ON live_recordings FOR EACH ROW EXECUTE FUNCTION dg_native_live_capture_guard();
CREATE FUNCTION dg_native_commit_live_capture(target text,token text,rid text,snapshot_text text,snapshot_digest text,guard_text text,guard_digest text,receipt_text text,receipt_digest text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r live_outputs;s live_sessions;v jsonb:=receipt_text::jsonb;g jsonb:=guard_text::jsonb;o jsonb:=v->'object';poster jsonb:=v->'poster';spec jsonb:=v->'specs';at_time text:=dg_utc_now();aid text:=v->>'assetId';uid text:=v->>'uploadId';
BEGIN
 SELECT * INTO STRICT r FROM live_outputs WHERE id=target FOR UPDATE;SELECT * INTO STRICT s FROM live_sessions WHERE id=r.session_id;
 IF NOT COALESCE(aid ~ '^[a-f0-9-]{36}$' AND uid ~ '^[a-f0-9-]{36}$' AND rid ~ '^[a-f0-9-]{36}$' AND jsonb_typeof(v->'object')='object' AND jsonb_typeof(v->'poster')='object' AND jsonb_typeof(spec)='object' AND v->>'schemaVersion'='1' AND v->>'pipeline'='native-live-output-capture-v1' AND g->>'pipeline'='native-live-output-capture-v1' AND jsonb_typeof(g->'outputId')='string' AND jsonb_typeof(g->'outputHash')='string' AND jsonb_typeof(g->'sessionHash')='string' AND jsonb_typeof(g->'expiresAt')='string' AND g->>'partsHash' ~ '^[a-f0-9]{64}$' AND v->>'expiresAt'=g->>'expiresAt' AND v->>'partsHash'=g->>'partsHash' AND o->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$' AND o->>'sha256' ~ '^[a-f0-9]{64}$' AND (o->>'size')::bigint BETWEEN 1 AND 134217728 AND poster->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$' AND poster->>'sha256' ~ '^[a-f0-9]{64}$' AND(poster->>'size')::bigint BETWEEN 1 AND 8388608 AND(spec->>'width')::bigint=1280 AND(spec->>'height')::bigint=720 AND(spec->>'fps')::bigint=24 AND(spec->>'durationMs')::bigint BETWEEN 1 AND 1803000 AND(spec->>'hasAudio')::bigint=1 AND(spec->>'sampleRate')::bigint=48000 AND(spec->>'channels')::bigint=2,false) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Capture requires a complete bounded actual media receipt';END IF;
 IF r.status<>'stopping' OR r.lease_token IS DISTINCT FROM token OR r.lease_until<=at_time OR r.invalidated_at IS NOT NULL OR r.withdrawn_at IS NOT NULL OR s.invalidated_at IS NOT NULL OR s.status<>'ended' OR s.kind='preview' OR s.snapshot::jsonb->'definition'->>'recordingEnabled'<>'true' OR NOT EXISTS(SELECT 1 FROM memberships m WHERE m.user_id=r.actor_id AND m.tenant_id=r.tenant_id AND m.role IN('admin') AND m.workspace_ids::jsonb ? r.workspace_id) OR NOT EXISTS(SELECT 1 FROM live_output_parts WHERE output_id=target AND kind='segment') OR EXISTS(SELECT 1 FROM live_output_recordings WHERE output_id=target) OR receipt_digest<>encode(sha256(convert_to(receipt_text,'UTF8')),'hex') OR snapshot_digest<>encode(sha256(convert_to(snapshot_text,'UTF8')),'hex') OR guard_digest<>encode(sha256(convert_to(guard_text,'UTF8')),'hex') OR v->>'pipeline'<>'native-live-output-capture-v1' OR g->>'pipeline'<>'native-live-output-capture-v1' OR g->>'outputId'<>r.id OR g->>'outputHash'<>r.snapshot_hash OR g->>'sessionHash'<>s.snapshot_hash OR g->>'expiresAt'<=at_time OR v->>'expiresAt'<>g->>'expiresAt' OR v->>'partsHash'<>g->>'partsHash' OR o->>'storage_key' !~ '^[a-f0-9-]{36}\.bin$' OR poster->>'storage_key' !~ '^[a-f0-9-]{36}\.bin$' OR o->>'sha256' !~ '^[a-f0-9]{64}$' OR poster->>'sha256' !~ '^[a-f0-9]{64}$' OR (o->>'size')::bigint NOT BETWEEN 1 AND 134217728 OR(poster->>'size')::bigint NOT BETWEEN 1 AND 8388608 OR(spec->>'width')::bigint<>1280 OR(spec->>'height')::bigint<>720 OR(spec->>'fps')::bigint<>24 OR(spec->>'durationMs')::bigint NOT BETWEEN 1 AND 1803000 OR(spec->>'hasAudio')::bigint<>1 OR(spec->>'sampleRate')::bigint<>48000 OR(spec->>'channels')::bigint<>2 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Actual local capture is not bound to a valid stopped output lease';END IF;
 INSERT INTO uploads VALUES(uid,r.tenant_id,r.workspace_id,r.actor_id,o->>'storage_key',o->>'sha256',(o->>'size')::bigint,'video/mp4',spec::text,at_time);
 INSERT INTO assets(id,tenant_id,workspace_id,upload_id,name,category,synthetic,expires_at,created_at) VALUES(aid,r.tenant_id,r.workspace_id,uid,'本地连续输出实际录制','reference',1,v->>'expiresAt',at_time);
 INSERT INTO _dg_native_asset_origins VALUES(aid,uid,r.tenant_id,r.workspace_id,o->>'sha256',(o->>'size')::bigint,'live_recording','mock',r.app_env,at_time);
 INSERT INTO video_sources VALUES(aid,poster->>'storage_key',poster->>'sha256',(poster->>'size')::bigint,at_time);
 INSERT INTO live_recordings(id,session_id,tenant_id,workspace_id,actor_id,snapshot,snapshot_hash,source_guard,source_guard_hash,status,attempts,asset_id,storage_key,size,sha256,environment,app_env,created_at,updated_at,capture_kind) VALUES(rid,s.id,r.tenant_id,r.workspace_id,r.actor_id,snapshot_text,snapshot_digest,guard_text,guard_digest,'ready',1,aid,o->>'storage_key',(o->>'size')::bigint,o->>'sha256','mock',r.app_env,at_time,at_time,'local_continuous_output');
 INSERT INTO _dg_native_live_captures VALUES(rid,r.id,receipt_text,receipt_digest,at_time);INSERT INTO live_recording_origins VALUES(aid,rid);INSERT INTO live_output_recordings VALUES(rid,r.id,g->>'partsHash');
 INSERT INTO asset_versions VALUES(aid,1,jsonb_build_object('id',aid,'workspaceId',r.workspace_id,'name','本地连续输出实际录制','category','reference','version',1,'archived',false,'synthetic',true,'expiresAt',v->>'expiresAt','createdAt',at_time,'mediaType','video/mp4','size',(o->>'size')::bigint,'sha256',o->>'sha256','specs',spec)::text,at_time);RETURN rid;
END $dg$;
REVOKE ALL ON FUNCTION dg_native_output_guard(),dg_native_output_span_guard(),dg_native_output_generation_guard(),dg_native_output_presentation_guard(),dg_native_output_member_invalidate(),dg_native_live_capture_guard(),dg_native_commit_live_capture(text,text,text,text,text,text,text,text,text) FROM PUBLIC;
